import AppKit

enum Artwork {
    static let headphones: NSImage = load(headphonesData, template: false)
    static let dsee: NSImage = load(dseeData, template: true)

    private static func load(_ encoded: String, template: Bool) -> NSImage {
        guard let data = Data(base64Encoded: encoded), let image = NSImage(data: data) else { return NSImage() }
        image.isTemplate = template
        return image
    }

    private static let headphonesData = ""

    private static let dseeData = ""
}
